CREATE TABLE IF NOT EXISTS product_analytics_daily (day DATE NOT NULL, tenant_id TEXT NOT NULL, product_id BIGINT NOT NULL, revenue NUMERIC(18,2) NOT NULL DEFAULT 0, usage_units NUMERIC(18,6) NOT NULL DEFAULT 0, payments_succeeded INT NOT NULL DEFAULT 0, payments_failed INT NOT NULL DEFAULT 0, refunds INT NOT NULL DEFAULT 0, trust_score NUMERIC(5,2) NOT NULL DEFAULT 0, PRIMARY KEY(day,tenant_id,product_id)); CREATE OR REPLACE VIEW vw_first_payment_month AS SELECT tenant_id, COALESCE(product_id,0) AS product_id, DATE_TRUNC('month', MIN(received_at))::date AS first_payment_month FROM billing_event_log WHERE (event_type ILIKE '%invoice.paid%' OR event_type ILIKE '%payment.succeeded%') GROUP BY tenant_id, COALESCE(product_id,0);